                            "text": `นัดหมายวันที่ ${scheduleDate}`, 
                            "weight": "bold", 
                            "size": "xl", 
                            "color": "#FFFFFF", 
                            "margin": "md" 
                        }
                    ]
                },
                "body": {
                    "type": "box",
                    "layout": "vertical",
                    "paddingAll": "xl",
                    "spacing": "md",
                    "contents": [
                        // Summary Count
                        { 
                            "type": "text", 
                            "text": `รวม ${appointments.length} รายการที่ต้องนำเสนอ:`, 
                            "weight": "bold", 
