                            "margin": "none" 
                        },
                        { "type": "separator", "margin": "md" },
                        // List of Appointments (Dynamic)
                        {
                            "type": "box",
                            "layout": "vertical",
                            "spacing": "xl",
                            "contents": appointmentContents
                        }
                    ]
