// เรียกใช้ Memory Global (ต้องมี $ นำหน้าครับ)
const sd = $getWorkflowStaticData('global');

// ดึงข้อมูล Event จาก Node Webhook โดยตรง
const event = $('Webhook1').first().json.body.events[0];

const userId = event.source.userId;
const groupId = event.source.groupId || null;
// บันทึก State ลง Memory
sd[userId] = {
  step: 'WAIT_DETAIL',
  groupId: groupId, 
  timestamp: new Date().getTime()
};

return [{ json: { status: "State Saved", userId: userId, step: "WAIT_DETAIL" } }];

// เรียกความจำ Global
const sd = $getWorkflowStaticData('global');

// ดึงข้อมูลคนส่งล่าสุด
const event = $('Webhook').first().json.body.events[0];
const userId = event.source.userId;

// ดึง State จาก Memory
let state = sd[userId];

// ----------------------------------------------------
// 🟢 ส่วนเสริมพิเศษ: ช่วยให้ Test ผ่าน (Mock Data)
// ถ้า Memory ว่าง (เพราะเรากด Test แยก) ให้สมมติว่ามีสถานะอยู่เลย
if (!state) {
   state = { step: 'WAIT_DETAIL', groupId: event.source.groupId || 'GROUP-TEST' };
}
// ----------------------------------------------------

if (state && state.step === 'WAIT_DETAIL') {
  return [{
    json: {
      raw_message: event.message.text || "มีรูปภาพแนบ",
      message_type: event.message.type,
      message_id: event.message.id,
      userId: userId,
      groupId: state.groupId,
      ticket_source: "LINE"
    }
  }];
} else {
  return [];
}

const text = ($json.raw_message || '').toLowerCase(); // แปลงเป็นตัวเล็กเพื่อง่ายต่อการเช็ค

// 1. ตั้งค่า Default (ถ้าหาไม่เจอ ให้เป็น Incident P3 ไว้ก่อน)
let type = 'Incident';
let priority = 'P3';
let sla_minutes = 480; // 8 ชม.

// 2. เช็คว่าเป็น REQUEST หรือไม่?
// คำค้นหา: ขอ, request, เพิ่ม, ปรับ, แก้ไข, รายงาน, ข้อมูล, report
const requestKeywords = ['ขอ', 'request', 'เพิ่ม', 'ปรับ', 'แก้ไข', 'รายงาน', 'ข้อมูล', 'report'];

if (requestKeywords.some(k => text.includes(k))) {
  type = 'Request';
  priority = 'P4';
  sla_minutes = 1440; // 24 ชม.
} 

// 3. ถ้าไม่ใช่ Request -> เช็คระดับความรุนแรงของ INCIDENT
if (type === 'Incident') {
  if (text.includes('ล่ม') || text.includes('ใช้งานไม่ได้ทั้งหมด') || text.includes('เข้าไม่ได้')) {
    // P1: ระบบล่ม
    priority = 'P1';
    sla_minutes = 43;
  } else if (text.includes('ทำงานไม่ได้') || text.includes('กระทบงานหลัก') || text.includes('error')) {
    // P2: กระทบงานหลัก
    priority = 'P2';
    sla_minutes = 240; // 4 ชม.
  } else if (text.includes('บางส่วน') || text.includes('บางเมนู')) {
    // P3: กระทบบางส่วน
    priority = 'P3';
    sla_minutes = 480; // 8 ชม.
  } else {
    // P4: ไม่เร่งด่วน (Default Incident)
    priority = 'P4';
    sla_minutes = 1440; // 24 ชม.
  }
}

// ส่งค่ากลับไป
return [{
  json: {
    ...$json, // เอาข้อมูลเก่าไปด้วย (userId, message)
    type: type,
    priority: priority,
    sla_minutes: sla_minutes
  }
}];

// ดึงเวลาปัจจุบัน
const now = new Date();

// สร้างส่วนประกอบของ Ticket ID (Format: OCM-YYMMDD-XXX)
const y = now.getFullYear().toString().slice(2); // เอาปี 2 ตัวท้าย (เช่น 25)
const m = String(now.getMonth() + 1).padStart(2, '0'); // เดือน
const d = String(now.getDate()).padStart(2, '0'); // วัน
const randomNum = Math.floor(Math.random() * 900 + 100); // สุ่มเลข 3 หลัก

const ticket_id = `OCM-${y}${m}${d}-${randomNum}`;

// คำนวณ Due Date (เวลาปัจจุบัน + นาที SLA)
// แปลง sla_minutes เป็นมิลลิวินาที ( * 60 * 1000)
const slaMinutes = $json.sla_minutes || 0;
const due_at = new Date(now.getTime() + slaMinutes * 60 * 1000);

// ส่งค่ากลับไป
return [{
  json: {
    ...$json, // เอาข้อมูลเก่าไปด้วย
    ticket_id: ticket_id,
    created_at: now.toISOString(),
