const machines = [];

while ((match = regex.exec(text)) !== null) {

  // แปลงค่าเป็นตัวเลขเพื่อนำมาเช็คเงื่อนไข
  const cpu = parseFloat(match[4]);
  //const cpu = 95; // บังคับให้เป็น 95 เพื่อทดสอบ
  const mem = parseFloat(match[5]);
  const disk = parseFloat(match[6]);
  const status = match[8];

  // --- ส่วนที่เพิ่มใหม่: Logic เช็คระดับความรุนแรง ---
  let alertLevel = "NORMAL";
  let alertColor = "#00C853"; // สีเขียว
  let alertMsg = "สถานะปกติ";

  // เช็คเงื่อนไข: > 80 = CRITICAL (ไม่ปกติ)
  if (cpu > 80 || mem > 80 || disk > 80 || status !== 'ONLINE') {
    alertLevel = "CRITICAL";
    alertColor = "#D32F2F"; // สีแดงเข้ม
    alertMsg = "🚨 ผิดปกติ (Critical)";
  } 
  // เช็คเงื่อนไข: 60-80 = WARNING (เฝ้าระวัง)
  else if (cpu > 60 || mem > 60 || disk > 60) {
    alertLevel = "WARNING";
    alertColor = "#FFC107"; // สีเหลือง/ส้ม
    alertMsg = "⚠️ เฝ้าระวัง (Warning)";
  }

  machines.push({
    json: {
      date: reportDate,
      no: parseInt(match[1]),
      vm_name: match[2].trim(),
      ip_address: match[3],
      cpu: cpu,
      memory: mem,
      disk: disk,
      health: parseInt(match[7]),
      status: status,
      // ส่งค่าพวกนี้ไปใช้ต่อ
      alert_level: alertLevel,
      alert_color: alertColor,
      alert_msg: alertMsg
    }
  });
}

return machines;

// รับข้อมูลจาก Gmail
const text = items[0].json.text || items[0].json.snippet || "";
const subject = items[0].json.subject || "";

// ฟังก์ชันทำความสะอาดข้อความ (สำคัญ! แก้ Error JSON พัง)
function cleanText(str) {
  if (!str) return null;
  // 1. ลบช่องว่างหน้า-หลัง
  // 2. เปลี่ยนการขึ้นบรรทัดใหม่ (\n, \r) ให้เป็นช่องว่าง
  // 3. Escape ฟันหนู (") กัน JSON พัง
  return str.trim().replace(/[\r\n]+/g, ' ').replace(/"/g, '\\"');
}

// ฟังก์ชันแกะข้อมูล (อัปเกรดใหม่ ใช้ cleanText ช่วย)
function extract(key) {
  const regex = new RegExp(`${key}:\\s*([\\s\\S]*?)(?:\\s+(?:IP|Severity|Status|Problem|Date):|$)`, 'i');
  const match = text.match(regex);
  return match ? cleanText(match[1]) : null;
}

// 1. ดึงค่าต่างๆ ออกมา
let host = extract("Host") || "ไม่ระบุ";
let ip = extract("IP") || "ไม่ระบุ";
let severity = extract("Severity") || "Warning";
let problem = extract("Problem");
let date = extract("Date") || new Date().toLocaleString('th-TH');

// 2. ระบบสำรอง: ถ้าแกะ Problem ไม่ได้ ให้เอาจาก Subject
if (!problem || problem === "ไม่ระบุ") {
    // ลบคำนำหน้าและทำความสะอาด
    let rawSubject = subject.replace(/^(PROBLEM|RESOLVED):\s*/i, "");
    problem = cleanText(rawSubject);
}

// 3. ตรวจสอบสถานะ (Recovery)
let isRecovery = false;
if (subject.toLowerCase().includes("resolved") || subject.toLowerCase().includes("ok") || (extract("Status") || "").toLowerCase().includes("resolved")) {
  isRecovery = true;
}

// 4. กำหนดสีและหัวข้อ
let msg_color = "#D32F2F"; // 🔴 สีแดง
let msg_title = "🔴 แจ้งเตือนปัญหา";
let msg_status_text = "มีเหตุขัดข้อง";

if (isRecovery) {
  msg_color = "#00C853"; // 🟢 สีเขียว
  msg_title = "🟢 ระบบปกติแล้ว";
  msg_status_text = "ได้รับการแก้ไขแล้ว";
  severity = "Normal"; 
}

// ส่งค่าออกไป
return [{
  json: {
    host: host,
    ip: ip,
    severity: severity,
    problem: problem, 
    date: date,
    msg_title: msg_title,
    msg_color: msg_color,
    msg_status_text: msg_status_text
  }
}];

