parameters.jsCode:
// รับข้อมูลทั้งหมดที่ทำเสร็จจาก Loop
const allItems = $input.all();

// สร้างข้อความสรุปแค่ 1 รายการ
return {
  json: {
    // สังเกตตรง \\n นะครับ ต้องใช้ 2 ขีด เพื่อให้ JSON เข้าใจว่าเป็นคำสั่งขึ้นบรรทัดใหม่
    summary: `✅ งานเสร็จสิ้น!\\nอัปเดตข้อมูลทั้งหมด ${allItems.length} บริษัท เรียบร้อยแล้วครับ`
  }
};

// 1. รับข้อมูลแถวทั้งหมดจาก Google Sheet
const allRows = items.map(item => item.json);

// 2. หาวันที่ปัจจุบัน (Format: 9/2/2026)
const today = new Date();
const day = today.getDate();
const month = today.getMonth() + 1;
const year = today.getFullYear();
const todayStr = `${day}/${month}/${year}`; 

// 3. กรองหาแถวที่ "วันที่ติดต่อล่าสุด" ตรงกับ "วันนี้"
const worksToday = allRows.filter(row => {
  // แก้ 'Timestamp' หรือ 'วันที่ติดต่อล่าสุด' ให้ตรงกับชื่อคอลัมน์วันที่ของคุณ
  const rowDate = row['วันที่ติดต่อล่าสุด'] || row['Timestamp'] || ''; 
  return rowDate.toString().includes(todayStr);
});

// -------------------------------------------------------
// 🆕 ส่วนที่เพิ่มใหม่: นับจำนวนที่ Synced แล้ว
// -------------------------------------------------------
const syncedCount = worksToday.filter(row => {
  // เช็คว่าคอลัมน์ 'Synced' มีข้อมูลไหม (ไม่ว่าง)
  // ถ้าชื่อคอลัมน์ใน Sheet ไม่ใช่ 'Synced' ให้แก้ตรงนี้ครับ
  const status = row['Synced']; 
  return status && status.toString().trim() !== ''; 
}).length;

// สรุปยอดรวม
const totalCount = worksToday.length;
const pendingCount = totalCount - syncedCount; // (เผื่ออยากรู้ยอดที่ยังไม่ Sync)

// 4. สร้างข้อความส่ง Telegram
return {
  json: {
    message: `📊 <b>สรุปยอดงานประจำวัน</b> (${todayStr})
------------------------------
📥 <b>พบรายการใหม่วันนี้:</b> ${totalCount} รายการ
✅ <b>Synced แล้ว:</b> ${syncedCount} รายการ
⏳ <b>รอดำเนินการ:</b> ${pendingCount} รายการ
------------------------------
<i>(ข้อมูล ณ เวลา 19:00 น.)</i>`
  }
};

const now = new Date();
const returnData = [];

// ฟังก์ชันแปลงวันที่ไทย (GMT+7) เป็น UTC
function parseThaiDate(dateStr) {
    if (!dateStr) return null;
    const [datePart, timePart] = dateStr.split(' ');
    if (!datePart || !timePart) return null;

    const [day, month, year] = datePart.split('/');
    const [hour, minute] = timePart.split(':');

    // ลบ 7 ชั่วโมงออกจากเวลาไทย เพื่อเป็น UTC
    return new Date(Date.UTC(year, month - 1, day, hour - 7, minute));
}

for (const item of $input.all()) {
    const data = item.json;

    // --- 1. ดึงค่า (ใช้ชื่อสั้นๆ ที่แก้ใน Sheet แล้ว) ---
    // ใช้ || เพื่อกันเหนียว (เผื่อลืมแก้ชื่อใน Sheet ก็ยังพอดึงชื่อยาวได้บ้าง)
    const status = data['status'];
    const createdAtStr = data['created_at']; 
    const slaMinutes = parseInt(data['sla_minutes'] || data['# sla_minutes'] || 0); 
    const notifiedAt = data['notified_at'] || data['notified_overdue_at'];
    const channelId = data['channel_id'] || data['channel'];

    // Debug: ปริ้นท์ดูว่าอ่านค่าได้ไหม (กดดูใน Console Log)
    console.log(`Checking Ticket: ${data['ticket_id']}, SLA: ${slaMinutes}, Created: ${createdAtStr}`);

    // --- 2. กรองเคส ---
    if (status === 'Resolved' || status === 'Closed') continue;
    if (!createdAtStr || !slaMinutes) continue; // ถ้าไม่มี SLA จะข้ามตรงนี้

    // --- 3. คำนวณเวลา ---
    const createdAt = parseThaiDate(createdAtStr);
    if (!createdAt) continue;

    const dueAt = new Date(createdAt.getTime() + (slaMinutes * 60000));

    // คำนวณส่วนต่าง (นาที)
    const diffMs = now.getTime() - dueAt.getTime();
    const overdueMinutes = Math.floor(diffMs / 60000);

    console.log(`>> Ticket: ${data['ticket_id']} | Overdue: ${overdueMinutes} mins`); // Debug

    // --- 4. เงื่อนไข: เกินเวลา (>0) และ ยังไม่เคยแจ้งเตือน ---
    if (overdueMinutes > 0 && (!notifiedAt || notifiedAt.toString().trim() === '')) {

        const priority = data['priority (P1/P2/P3)'] || '-';
        const type = data['type (Incident/Request)'] || '-';
        const subject = data['Subject'] || '-';
        const ticketId = data['ticket_id'] || '-';

        const msg = `🚨 SLA Ticket Overdue 🚨\n\n` +
                    `Ticket ID: ${ticketId}\n` +
                    `Type: ${type}\n` +
                    `Priority: ${priority}\n` +
                    `Status: ${status || 'New'}\n\n` +
                    `⚠️ เกินกำหนดมาแล้ว: ${overdueMinutes} นาที\n` +
                    `หัวข้อ: ${subject}`;

        returnData.push({
            json: {
                ...data,
                overdue_minutes: overdueMinutes,
                message_text: msg,
                line_to: channelId,
                targetRow: item.index + 2 
            }
        });
    }
}

return returnData;

const returnData = [];

// วนลูปเช็ค Ticket ทุกบรรทัด
for (const item of $input.all()) {
    const data = item.json;

    // --- โซนจับคู่ชื่อคอลัมน์ (แก้ไขชื่อให้ตรงกับ Google Sheet) ---
    const status = data['status']; 
    // แก้ชื่อ field ให้ตรงกับ Input ที่เห็นด้านซ้าย
    const notifiedClosed = data['notified_closed_at']; 
    const lineTo = data['channel_id'];
    // ------------------------------------------------

    // เงื่อนไข: 
    // 1. สถานะเป็น Resolved หรือ Closed
    // 2. ยังไม่เคยแจ้งเตือน (!notifiedClosed) หรือเป็นค่าว่าง
    // 3. (สำคัญ) ต้องมี User ID (lineTo) ด้วย ไม่งั้นส่งไม่ได้
    if (
        (status === 'Resolved' || status === 'Closed') && 
        (!notifiedClosed || notifiedClosed.toString().trim() === '') &&
        lineTo // <--- ถ้าชื่อตัวแปร lineTo ผิด บรรทัดนี้จะเป็น false ทำให้ไม่มี output
    ) {

        const ticketId = data['ticket_id'];
        const subject = data['Subject'] || '-';
        const fixDetail = data['Fix'] || 'ตรวจสอบและแก้ไขเรียบร้อยแล้ว';

        const msg = `✅ ปิดเคสเรียบร้อย (Resolved)\n\n` +
                    `Ticket ID: ${ticketId}\n` +
                    `อาการ: ${subject}\n\n` +
                    `🛠️ การแก้ไข: ${fixDetail}\n\n` +
                    `ขอบคุณที่ใช้บริการครับ 🙏`;

        returnData.push({
            json: {
                ...data,
                message_text: msg,
                line_to: lineTo,
                targetRow: data.row_number || (item.index + 2) 
            }
        });
    }
}

return returnData;

// เรียกความจำ Global
const sd = $getWorkflowStaticData('global');

// ดึง UserId จาก Webhook (ต้นทาง)
const userId = $('Webhook').item.json.body.events[0].source.userId;

// ลบข้อมูลสถานะทิ้ง (จบงาน)
if (userId && sd[userId]) {
  delete sd[userId];
}

return [{ json: { status: "State Cleared", userId: userId, finished: true } }];

