parameters.jsCode:
// === 1. ดึงข้อมูลแบบข้ามโหนด ===
// ดึงข้อมูลฟอร์มจากโหนด Merge (ตัวพิมพ์เล็ก-ใหญ่ชื่อโหนดต้องเป๊ะ)
const data = $('Merge').first().json;
// ดึงข้อมูลโปรไฟล์ LINE จาก HTTP Request ที่เพิ่งรันเสร็จ
const lineProfile = $input.item.json;

// === 2. ฟังก์ชันจัดการเวลาไทย (GMT+7) ===
function formatThaiDate(d) {
    const tzDate = new Date(d.getTime() + (7 * 60 * 60 * 1000));
    const dd = String(tzDate.getUTCDate()).padStart(2, '0');
    const mm = String(tzDate.getUTCMonth() + 1).padStart(2, '0');
    const yyyy = tzDate.getUTCFullYear();
    const hh = String(tzDate.getUTCHours()).padStart(2, '0');
    const min = String(tzDate.getUTCMinutes()).padStart(2, '0');
    return `${dd}/${mm}/${yyyy} ${hh}:${min}`;
}

// === 3. วิเคราะห์ความเร่งด่วน (SLA Logic) ===
const text = (data.subject || '').toLowerCase();
let priority = 'P3';
let sla_minutes = 480; 
let issueType = data.issueType || 'Incident';
let headerColor = '#1DB446'; 
let headerIcon = '✅';
let headerText = 'New Incident';

if (issueType === 'Request') {
    priority = 'P4';
    sla_minutes = 1440;
    headerColor = '#1976D2'; 
    headerIcon = '📝';
    headerText = 'New Request';
} else {
    if (text.includes('ล่ม') || text.includes('ไม่ได้') || text.includes('critical') || text.includes('downtime')) {
        priority = 'P1';
        sla_minutes = 60;
        headerColor = '#D32F2F'; 
        headerIcon = '🚨';
        headerText = 'Critical Incident';
    } else if (text.includes('error') || text.includes('fail') || text.includes('ช้า')) {
        priority = 'P2';
        sla_minutes = 120;
        headerColor = '#FF9800'; 
        headerIcon = '⚠️';
        headerText = 'High Priority Incident';
    }
}

// === 4. สร้าง Ticket ID และคำนวณเวลา ===
const now = new Date();
const dateStr = now.toISOString().slice(2,10).replace(/-/g, '');
const rand = Math.floor(Math.random() * 900 + 100);
const ticketId = `OCM-${dateStr}-${rand}`;

const formattedCreated = formatThaiDate(now);
const due_at = new Date(now.getTime() + sla_minutes * 60000);
const formattedDue = formatThaiDate(due_at);

// === จุดสำคัญ: นำตัวแปร displayName ของ LINE มาใช้งาน ===
const reporterName = lineProfile.displayName || 'Unknown';

// === 5. สร้าง Payload LINE Flex Message ===
const linePayload = {
    to: data.userId,
    messages: [{
        type: "flex",
        altText: `${headerIcon} ${headerText}: ${ticketId}`,
        contents: {
            type: "bubble",
            size: "mega", 
            header: {
                type: "box",
                layout: "vertical",
                backgroundColor: headerColor,
                paddingAll: "8px",
                contents: [ { type: "spacer", size: "xs" } ] 
            },
            body: {
                type: "box",
                layout: "vertical",
                spacing: "md",
                contents: [
                    {
                        type: "text",
                        text: `${headerIcon} ${headerText}`,
                        weight: "bold",
                        size: "xl",
                        color: headerColor,
                        wrap: true
                    },
                    { type: "separator", margin: "md" },
                    {
                        type: "box", layout: "vertical", spacing: "sm",
