return [
  {
    json: {
      name: "Tally Form",
      url: "https://tally.so/r/obDoaN?userid=U39ad8f7118178f72fa5a8dde0b1c598a"
    }
  },
  {
    json: {
      name: "OneClimate Feedback",
      url: "https://oneclimate-feedback-form.lovable.app/"
    }
  }
  // อยากเพิ่มเว็บอีก ก็ copy block {} มาต่อท้ายได้เลย
];

// ดึงข้อมูลความจำเดิม (Static Data)
const staticData = $getWorkflowStaticData('global');
const statusMap = staticData.statusMap || {}; // สมุดจดสถานะแยกรายเว็บ

// ดึงข้อมูลต้นทาง (ชื่อเว็บ/URL) จาก Node แรก
const inputItems = items;
const originalItems = $('Define Websites').all(); 

const results = [];

for (let i = 0; i < inputItems.length; i++) {
  // จับคู่ผลลัพธ์จาก curl (inputItems) กับข้อมูลเว็บ (originalItems) ด้วยลำดับ (Index)
  const curlResult = inputItems[i].json;
  const siteInfo = originalItems[i].json; 

  const url = siteInfo.url;
  const name = siteInfo.name;

  // แปลงผลลัพธ์เป็น Status
  // ถ้า curl error ไม่มี stdout ให้ถือว่า Down (000)
  const codeStr = (curlResult.stdout) ? curlResult.stdout.toString().trim() : '000';
  const codeInt = parseInt(codeStr);

  // กฎ: 200-299 คือ UP, ที่เหลือคือ DOWN
  const currentStatus = (codeInt >= 200 && codeInt < 300) ? 'UP' : 'DOWN';

  // ดึงค่าเก่ามาเทียบ
  const lastStatus = statusMap[url] || 'UP'; // เริ่มต้นถือว่าดีไว้ก่อน

  let alertType = 'NONE';
  if (lastStatus === 'UP' && currentStatus === 'DOWN') {
    alertType = 'ALERT_DOWN';
  } else if (lastStatus === 'DOWN' && currentStatus === 'UP') {
    alertType = 'ALERT_RECOVER';
  }

  // อัปเดตสถานะล่าสุด
  statusMap[url] = currentStatus;

  // ส่งข้อมูลออกไป
  results.push({
    json: {
      alert_type: alertType,
      name: name,          // ส่งชื่อเว็บไปโชว์
      url: url,            // ส่ง URL ไป
      status_code: codeStr,
      status_text: currentStatus,
      readable_date: $('Schedule Trigger10').first().json["Readable date"],
      readable_time: $('Schedule Trigger10').first().json["Readable time"]
    }
  });
}

// บันทึกความจำ
staticData.statusMap = statusMap;

return results;

