                "cornerRadius": "lg",
                "borderWidth": "medium",
                "borderColor": "#e0e0e0",
                "paddingAll": "md",
                "margin": "md",
                "contents": [
                    // Row 1: Company + Time | BD Badge
                    {
                        "type": "box",
                        "layout": "horizontal",
                        "contents": [
                            // Company + Time
                            {
                                "type": "box",
                                "layout": "vertical",
                                "flex": 3,
                                "contents": [
                                    {
                                        "type": "text",
