// 1. ดึงข้อมูล Pivot (ปัจจุบัน)
const pivotItems = $('Get row(s) in sheet19').all();

// 2. ดึงข้อมูล Log (อดีต)
const logItems = $('Get row(s) in sheet20').all();
const lastWeek = logItems.length > 0 ? logItems[0].json : {};

// ฟังก์ชันค้นหา
function getCurVal(keyword) {
  const row = pivotItems.find(i => {
    const stage = (i.json['Stage'] || '').toString();
    return stage.includes(keyword);
  });
  return row ? parseInt(row.json['COUNTA ของ บริษัท'] || 0) : 0;
}

// 3. Mapping ข้อมูล
const stats = {
  PO:       { cur: getCurVal('4. PO'),              last: parseInt(lastWeek.PO || 0) },
  Present:  { cur: getCurVal('2.1 Present แล้วสนใจ'), last: parseInt(lastWeek.Present || 0) },
  Brochure: { cur: getCurVal('1.1 สนใจรอ Slot') + getCurVal('1.2 ได้ Slot'), last: parseInt(lastWeek.Brochure || 0) },
  POC:      { cur: getCurVal('3.1 POC'),            last: parseInt(lastWeek.POC || 0) },

  // [แก้ไขจุดที่สั่ง]: เปลี่ยน Keyword จาก '3.2 QT' เป็น '3.3 POC และ QT'
  QT:       { cur: getCurVal('3.3 POC และ QT'),     last: parseInt(lastWeek.QT || 0) },

  Cancel:   { cur: getCurVal('6.2 Cancel Present'), last: parseInt(lastWeek.Cancel || 0) },
  Lost:     { cur: getCurVal('8. Lost'),            last: parseInt(lastWeek.Lost || 0) }
};

// 4. คำนวณ Trend
function calcTrend(curr, last, isGoodMetric) {
  const diff = curr - last;
  let percent = 0;
  if (last > 0) percent = Math.round((diff / last) * 100);

  let color = "#9CA3AF"; 
  let icon = ""; 
  let text = ""; 
  let hasChange = false; 

  if (diff > 0) {
    icon = "▲ " + diff;
    text = `▲ ${diff} (+${percent}%)`;
    color = isGoodMetric ? "#065F46" : "#991B1B";
    hasChange = true;
  } else if (diff < 0) {
    icon = "▼ " + Math.abs(diff);
    text = `▼ ${Math.abs(diff)} (${percent}%)`;
    color = isGoodMetric ? "#991B1B" : "#065F46";
    hasChange = true;
  }

  return { value: curr, icon: icon, text: text, color: color, hasChange: hasChange };
}

// 5. ประมวลผล
const po = calcTrend(stats.PO.cur, stats.PO.last, true);
const present = calcTrend(stats.Present.cur, stats.Present.last, true);
const brochure = calcTrend(stats.Brochure.cur, stats.Brochure.last, true);
const poc = calcTrend(stats.POC.cur, stats.POC.last, true);
const qt = calcTrend(stats.QT.cur, stats.QT.last, true);
const cancel = calcTrend(stats.Cancel.cur, stats.Cancel.last, false);
const lost = calcTrend(stats.Lost.cur, stats.Lost.last, false);

const today = new Date().toLocaleDateString('th-TH', { day: 'numeric', month: 'short', year: 'numeric' });

// ==========================================
// Helper Function: สร้างกล่องข้อมูลย่อย
// ==========================================
function createStatItem(label, dataObj, valueColor) {
    const contents = [
        { "type": "text", "text": `${dataObj.value}`, "size": "xl", "weight": "bold", "color": valueColor }
    ];

    if (dataObj.hasChange) {
        contents.push({ 
            "type": "text", 
            "text": dataObj.icon, 
            "size": "xs", 
            "color": dataObj.color, 
            "weight": "bold", 
            "margin": "sm" 
        });
    }

    return {
        "type": "box", "layout": "vertical", "flex": 1,
        "contents": [
            { "type": "text", "text": label, "size": "xxs", "color": "#6B7280", "align": "start", "wrap": true },
            {
                "type": "box", "layout": "baseline", "justifyContent": "flex-start",
                "contents": contents 
            }
        ]
    };
}

// ==========================================
// 6. เตรียมเนื้อหา PO CARD (Dynamic)
// ==========================================
const poContents = [];
poContents.push({ "type": "text", "text": "PURCHASE ORDER (PO)", "weight": "bold", "size": "xs", "color": "#FFFFFF", "align": "center", "wrap": true });
poContents.push({ "type": "text", "text": `${po.value}`, "weight": "bold", "size": "5xl", "color": "#FFFFFF", "align": "center", "margin": "sm" });

if (po.hasChange) {
    poContents.push({
       "type": "box", "layout": "horizontal",
       "contents": [ { "type": "text", "text": po.text, "size": "xs", "color": po.color, "weight": "bold", "align": "center" } ],
       "backgroundColor": "#D1FAE5", 
       "cornerRadius": "xxl",
       "paddingStart": "md", "paddingEnd": "md", "paddingTop": "xs", "paddingBottom": "xs",
       "margin": "sm", "justifyContent": "center"    
    });
}

// ==========================================
// 7. FLEX MESSAGE FINAL
// ==========================================
const flexMessage = {
  "type": "flex",
  "altText": `Weekly Update: PO ${po.value}`,
  "contents": {
    "type": "bubble",
    "size": "mega",
    "header": {
      "type": "box", "layout": "vertical",
      "contents": [
        {
          "type": "box", "layout": "horizontal",
          "contents": [
            { "type": "text", "text": "WEEKLY PERFORMANCE", "weight": "bold", "color": "#1E3A8A", "size": "xs", "flex": 1 },
            { "type": "text", "text": today, "size": "xxs", "color": "#6B7280", "align": "end" }
          ]
        },
        { "type": "text", "text": "Business Development Insight", "size": "lg", "weight": "bold", "color": "#111827", "margin": "xs", "wrap": true }
      ],
      "paddingAll": "lg",
      "backgroundColor": "#F3F4F6"
    },
    "body": {
      "type": "box", "layout": "vertical",
      "backgroundColor": "#F3F4F6", 
      "contents": [

        // --- 1. PO CARD (Green) ---
        {
          "type": "box", "layout": "vertical",
          "contents": poContents,    
          "alignItems": "center",    
          "paddingAll": "xxl",       
          "backgroundColor": "#047857", 
          "cornerRadius": "lg",
          "margin": "md"
        },

        // --- 2. PIPELINE CARD (White) ---
        {
           "type": "box", "layout": "vertical", "margin": "lg",
           "backgroundColor": "#FFFFFF", "cornerRadius": "lg", "paddingAll": "xl",           
           "contents": [
             { "type": "text", "text": "ACTIVE PIPELINE", "size": "xs", "weight": "bold", "color": "#4B5563", "margin": "sm", "align": "center" },
             { "type": "separator", "margin": "md", "color": "#F3F4F6" },
             // Row 1
             {
               "type": "box", "layout": "horizontal", "margin": "lg",
               "contents": [
                 createStatItem("Present แล้วสนใจ", present, "#1F2937"),
                 createStatItem("รอคิว/นัดนำเสนอ", brochure, "#1F2937")
               ]
             },
             // Row 2
             {
               "type": "box", "layout": "horizontal", "margin": "lg",
               "contents": [
                 createStatItem("POC (ทดสอบ)", poc, "#1F2937"),
                 createStatItem("POC และ QT", qt, "#1F2937")
               ]
             }
           ]
        },

        // --- 3. RISK CARD (White) ---
        {
           "type": "box", "layout": "vertical", "margin": "lg",
           "backgroundColor": "#FFFFFF", "cornerRadius": "lg", "paddingAll": "xl",
           "contents": [
             { "type": "text", "text": "RISK & LOSS", "size": "xs", "weight": "bold", "color": "#991B1B", "margin": "sm", "align": "center" },
             { "type": "separator", "margin": "md", "color": "#F3F4F6" },
             {
               "type": "box", "layout": "horizontal", "margin": "lg",
               "contents": [
                 createStatItem("หลุดหลัง Present", cancel, "#991B1B"),
                 createStatItem("Lost", lost, "#991B1B")
               ]
             }
           ]
        }
      ]
    },
    "footer": {
      "type": "box", "layout": "vertical", "spacing": "sm",
      "contents": [
        { 
          "type": "button", "style": "primary", "color": "#3B82F6", "height": "sm", 
          "action": { "type": "uri", "label": "ดูรายละเอียดทั้งหมด", "uri": "https://lookerstudio.google.com/u/0/reporting/dda8e9c9-7027-49f4-9eb7-37218d7f906a/page/p_wgxb5r4wzd" } 
        }
      ],
      "paddingAll": "lg",
      "backgroundColor": "#F3F4F6"
    }
  }
};

return {
  json: {
    flex_message: flexMessage,
    save_log: {
      Date: new Date().toISOString().split('T')[0],
      PO: stats.PO.cur,
      Present: stats.Present.cur,
      Brochure: stats.Brochure.cur,
      POC: stats.POC.cur,
      QT: stats.QT.cur,
      Cancel: stats.Cancel.cur,
      Lost: stats.Lost.cur
    }
  }
};

// สร้างวัตถุ Date ปัจจุบัน
const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1); 

// ⭐ แก้ไข: ไม่ใช้ padStart เพื่อให้ตรงกับ Google Sheets
const dd = String(tomorrow.getDate()); // 2 แทน 02
const mm = String(tomorrow.getMonth() + 1); // 12 แทน 12
const yyyy = tomorrow.getFullYear();

// ตัวแปรที่ใช้ในการค้นหาใน Google Sheet
const searchDate = `${dd}/${mm}/${yyyy}`; // 2/12/2025

console.log('Search Date:', searchDate); // ⭐ เพิ่ม log เพื่อ debug

return [{ json: { searchDate: searchDate, tomorrowDate: searchDate } }];

// --- โค้ดสำหรับ Node: Code in JavaScript4 (Data Preparation - Final) ---
const items = $input.all();
const appointmentsRaw = items.map(item => item.json);

const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);
const tomorrowDate = tomorrow.toLocaleDateString('th-TH', { 
    day: 'numeric', 
    month: 'long', 
    year: 'numeric' 
});

if (appointmentsRaw.length === 0) {
    return [{ 
        json: { 
            appointments: [], 
            searchDate: tomorrowDate 
        } 
    }];
}

// 1. แปลงข้อมูลทุกแถว
const detailedAppointments = appointmentsRaw.map(appt => {
    return {
        taxId: appt['TAX-ID'] || 'N/A',
        company: appt['บริษัท'] || 'N/A',
        source: appt['source'] || 'N/A',
        time: appt['เวลา'] || 'N/A',
        location: appt['สถานที่'] || 'N/A',
        bdContact: appt['BD นำเสนอ'] || 'N/A', 
        saleContact: appt['Sales'] || 'N/A', // ⭐ เพิ่มดึงคอลัมน์ J (แก้ไขคำว่า 'Sale' ให้ตรงกับชื่อหัวคอลัมน์ใน Sheet จริงๆ)
        date: appt[' นัดหมายนำเสนอ'] || tomorrowDate
    };
});

// 2. เรียงลำดับตามเวลา
detailedAppointments.sort((a, b) => {
    const timeA = parseFloat(a.time.replace('.', '').replace(':', ''));
    const timeB = parseFloat(b.time.replace('.', '').replace(':', ''));
    return timeA - timeB;
});

// 3. ส่ง Array ของนัดหมายทั้งหมดและวันที่ออกไป
return [{ 
    json: { 
        appointments: detailedAppointments, 
        searchDate: tomorrowDate 
    } 
}];

const input = $input.all()[0].json;
const appointments = input.appointments || [];
const scheduleDate = input.searchDate;

// แยกกลุ่มตามช่วงเวลา
const timeGroups = {
    morning: { label: '🌅 ช่วงเช้า', items: [], color: '#667eea' },
    afternoon: { label: '🌤️ ช่วงบ่าย', items: [], color: '#43a047' },
    evening: { label: '🌆 ช่วงเย็น', items: [], color: '#8e24aa' }
};

appointments.forEach(appt => {
    const timeParts = appt.time.split(/[.:]/);
    const hour = parseInt(timeParts[0]);

    if (hour < 12) {
        timeGroups.morning.items.push(appt);
    } else if (hour < 17) {
        timeGroups.afternoon.items.push(appt);
    } else {
        timeGroups.evening.items.push(appt);
    }
});

// สร้าง Content
const appointmentContents = [];

if (appointments.length === 0) {
    appointmentContents.push({
        "type": "text",
        "text": "🎉 วันพรุ่งนี้ไม่มีนัดหมายนำเสนอสินค้า/บริการครับ!",
        "weight": "bold",
        "color": "#1DB446",
        "size": "lg",
        "align": "center",
        "margin": "xl",
        "wrap": true
    });
} else {
    Object.values(timeGroups).forEach(group => {
        if (group.items.length === 0) return;

        // Section Title
        appointmentContents.push({
            "type": "box",
            "layout": "vertical",
            "backgroundColor": group.color,
            "cornerRadius": "md",
            "paddingAll": "sm",
            "margin": "lg",
            "contents": [
                {
                    "type": "text",
                    "text": `${group.label} (${group.items.length})`,
                    "weight": "bold",
                    "size": "sm",
                    "color": "#FFFFFF",
                    "align": "center"
                }
            ]
        });

        // Appointment Bubbles
        group.items.forEach((appt) => {
            const formattedTime = appt.time.includes(':') ? appt.time : appt.time.replace('.', ':');
            const timeDisplay = formattedTime + ' น.';

            // แปลง BD Contact (คงไว้ตามเดิม)
            let bdDisplay = appt.bdContact;
            let bdColor = "#333333";

            if (!bdDisplay || bdDisplay === 'N/A' || String(bdDisplay).includes('ไม่ระบุ')) {
                bdDisplay = '-';
                bdColor = "#cccccc";
            }

            appointmentContents.push({
                "type": "box",
                "layout": "vertical",
                "backgroundColor": "#FFFFFF",
                "cornerRadius": "lg",
                "borderWidth": "medium",
                "borderColor": "#e0e0e0",
                "paddingAll": "md",
                "margin": "md",
                "contents": [
                    // Row 1: Company + Time | BD Badge
                    {
                        "type": "box",
                        "layout": "horizontal",
                        "contents": [
                            {
                                "type": "box",
                                "layout": "vertical",
                                "flex": 3,
                                "contents": [
                                    {
                                        "type": "text",
                                        "text": String(appt.company || "-"),
                                        "weight": "bold",
                                        "size": "sm",
                                        "color": "#333333",
                                        "wrap": true,
                                        "maxLines": 3
                                    },
                                    {
                                        "type": "text",
                                        "text": timeDisplay,
                                        "size": "xs",
                                        "color": "#1DB446",
                                        "weight": "bold",
                                        "margin": "xs"
                                    }
                                ]
                            },
                            {
                                "type": "box",
                                "layout": "vertical",
                                "flex": 1,
                                "justifyContent": "flex-start",
                                "alignItems": "flex-end",
                                "contents": [
                                    {
                                        "type": "box",
                                        "layout": "vertical",
                                        "backgroundColor": "#f0f0f0",
                                        "cornerRadius": "md",
                                        "paddingAll": "xs",
                                        "contents": [
                                            {
                                                "type": "text",
                                                "text": String(bdDisplay),
                                                "size": "xs",
                                                "color": bdColor,
                                                "weight": "bold",
                                                "align": "center"
                                            }
                                        ]
                                    }
                                ]
                            }
                        ]
                    },
                    // Row 2: Location + Sale
                    {
                        "type": "box",
                        "layout": "horizontal",
                        "spacing": "md",
                        "margin": "sm",
                        "contents": [
                            {
                                "type": "text",
                                "text": `📍 ${appt.location || "-"}`, 
                                "size": "xs",
                                "color": "#999999",
                                "flex": 1,
                                "wrap": true
                            },
                            {
                                "type": "text",
                                "text": `👤 ${appt.saleContact || "-"}`, // ⭐ เปลี่ยนมาใช้ saleContact แทน source
                                "size": "xs",
                                "color": "#999999",
                                "flex": 0
                            }
                        ]
                    }
                ]
            });
        });
    });
}

// Summary by BD (คงไว้ตามเดิม)
const bdSummary = {};
