// 1. รับข้อมูล
const items = $input.all();

// 2. ตั้งเวลาปัจจุบัน (บังคับ Timezone ไทย)
const now = new Date(new Date().toLocaleString("en-US", {timeZone: "Asia/Bangkok"}));

// รีเซ็ตเวลาให้เป็น 00:00:00 ของวันนี้ (Start of Today)
const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());

// --- แก้ไขตรงนี้ (ให้เริ่มนับวันอาทิตย์) ---
const dayOfWeek = now.getDay(); // ค่าจะได้ 0=อาทิตย์, 1=จันทร์, ... 6=เสาร์
const startOfWeek = new Date(startOfToday);
// ถอยหลังไปหา "วันอาทิตย์" ล่าสุด (เช่น ถ้าวันนี้วันจันทร์ ก็ถอย 1 วัน)
startOfWeek.setDate(startOfToday.getDate() - dayOfWeek); 
// ----------------------------------------

// ตัวแปรเก็บยอด
let total = items.length;
let countToday = 0;
let countWeek = 0;

// ฟังก์ชันแก้วันที่ (Parse Date DD/MM/YYYY)
function parseThaiDate(dateStr) {
  if (!dateStr) return null;
  const parts = dateStr.toString().split(/[/\s:]/);
  if (parts.length >= 3) {
    // Format: วัน/เดือน/ปี (ปี, เดือน-1, วัน, ชม, นาที, วินาที)
    return new Date(parts[2], parts[1] - 1, parts[0], parts[3]||0, parts[4]||0, parts[5]||0);
  }
  return new Date(dateStr);
}

// 3. วนลูปนับยอด
for (const item of items) {
  const json = item.json;

  if (json.Timestamp) {
    const itemDate = parseThaiDate(json.Timestamp);

    // นับยอดวันนี้
    if (itemDate >= startOfToday) {
      countToday++;
    }

    // นับยอดสัปดาห์นี้ (รวมวันอาทิตย์ที่ผ่านมาด้วย)
    if (itemDate >= startOfWeek) {
      countWeek++;
    }
  }
}

// 4. จัดรูปแบบวันที่โชว์บนหัว
const thaiDate = now.getDate() + '/' + (now.getMonth() + 1) + '/' + (now.getFullYear() + 543);

// 5. สร้าง Flex Message
return {
  "flex_message": {
    "contents": {
      "type": "bubble",
      "size": "mega",
      "header": {
        "type": "box",
        "layout": "vertical",
        "contents": [
          {
            "type": "text",
            "text": "TAX-ID REGISTRATIONS",
            "color": "#FFFFFFcc",
            "size": "xs",
            "weight": "bold"
          },
          {
            "type": "text",
            "text": "สรุปยอดประจำวัน",
            "color": "#FFFFFF",
            "size": "xl",
            "weight": "bold",
            "margin": "xs"
          }
        ],
        "backgroundColor": "#128c8e",
        "paddingAll": "20px"
      },
      "body": {
        "type": "box",
        "layout": "vertical",
        "contents": [
          {
            "type": "text",
            "text": "ประจำวันที่ " + thaiDate,
            "color": "#888888",
            "size": "md",
            "align": "center"
          },
          { "type": "separator", "margin": "lg", "color": "#eeeeee" },
          {
            "type": "text",
            "text": "TODAY",
            "color": "#aaaaaa",
            "size": "sm",
            "weight": "bold",
            "align": "center",
            "margin": "lg"
          },
          {
            "type": "text",
            "text": countToday.toLocaleString(),
            "color": "#128c8e",
            "size": "5xl",
            "weight": "bold",
            "align": "center"
          },
          {
            "type": "text",
            "text": "รายการ",
            "color": "#aaaaaa",
            "size": "sm",
            "align": "center",
            "margin": "xs"
          },
          { "type": "separator", "margin": "xl", "color": "#eeeeee" },
          {
            "type": "box",
            "layout": "horizontal",
            "margin": "lg",
            "contents": [
              {
                "type": "box",
                "layout": "vertical",
                "contents": [
                  { "type": "text", "text": "THIS WEEK", "size": "xs", "color": "#aaaaaa", "weight": "bold", "align": "center" },
                  { "type": "text", "text": countWeek.toLocaleString(), "size": "xl", "color": "#333333", "weight": "bold", "align": "center", "margin": "sm" }
                ],
                "width": "50%"
              },
              { "type": "separator", "color": "#dddddd" },
              {
                "type": "box",
                "layout": "vertical",
                "contents": [
                  { "type": "text", "text": "TOTAL", "size": "xs", "color": "#aaaaaa", "weight": "bold", "align": "center" },
                  { "type": "text", "text": total.toLocaleString(), "size": "xl", "color": "#333333", "weight": "bold", "align": "center", "margin": "sm" }
                ],
                "width": "50%"
              }
            ]
          }
        ],
        "paddingAll": "20px"
      }
    }
  }
};

