const body = $input.item.json.body || $input.item.json;
const fields = body.data ? body.data.fields : body.fields;
const result = {};

if (fields && Array.isArray(fields)) {
  fields.forEach(field => {
    let value = '-';

    if (field.type === 'DROPDOWN' || field.type === 'MULTIPLE_CHOICE') {
       if (field.value && field.options) {
         const selected = field.options.find(opt => opt.id === field.value[0]);
         value = selected ? selected.text : '-';
       }
    } else if (field.type === 'FILE_UPLOAD' && field.value && field.value.length > 0) {
       value = field.value[0].url || '-';
    } else {
       value = field.value || '-';
    }

    if (field.label) result[field.label.trim()] = value;
    if (field.key) result[field.key] = value; 
  });
}

return {
  userId: result['userId'] || '-',
  reporter_name_tally: '-',
  customer: result['ชื่อลูกค้า'] || '-',
  service: result['ชื่อบริการ'] || '-',
  issueType: result['ประเภทปัญหา'] || 'Incident',
  subject: result['รายละเอียด/อาการ'] || '-',
  // เงื่อนไขดักจับ: ถ้าไม่มีรูป (เป็น '-') ให้ส่งค่า null ออกไป เพื่อไม่ให้ LINE API พัง
  imageUrl: (result['รูปภาพประกอบ (ถ้ามี)'] === '-' || !result['รูปภาพประกอบ (ถ้ามี)']) ? null : result['รูปภาพประกอบ (ถ้ามี)']
};

// 1. ดึงข้อความจาก Data Structure ปัจจุบันของ Gemini
let rawText = $input.item.json.content.parts[0].text;

// 2. ลบ Markdown ขยะ
rawText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

// 3. แปลง String เป็น JSON Object
let parsed = JSON.parse(rawText);

// 4. ฟังก์ชันแปลงวันที่ พ.ศ. → ค.ศ. + 2 หลัก → 4 หลัก
function convertDate(dateStr) {
  if (!dateStr) return dateStr;

  const match = dateStr.toString().match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
  if (!match) return dateStr;

  let [_, day, month, year] = match;
  year = parseInt(year);

  // 2 หลัก → 4 หลัก (26 → 2026)
  if (year < 100) {
    year = year + 2000;
  }

  // พ.ศ. → ค.ศ. (2569 → 2026)
  if (year > 2500) {
    year = year - 543;
  }

  return `${day.padStart(2,'0')}/${month.padStart(2,'0')}/${year}`;
}

// 5. แปลงทุก field ที่อาจเป็นวันที่
const dateFields = ['date', 'Date', 'meeting_date', 'Meeting_date', 'meetingDate'];
for (const field of dateFields) {
  if (parsed[field]) parsed[field] = convertDate(parsed[field]);
}

// 6. return เป็น array สำหรับ n8n
return [{ json: parsed }];

const items = $input.all();

// ── Timezone: Asia/Bangkok ──────────────────────────────────
function nowBKK() {
    return new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Bangkok' }));
}

function getWeekRange(date) {
    const d = new Date(date);
    const day = d.getDay();
    const diffToMonday = (day === 0) ? -6 : 1 - day;
    const monday = new Date(d);
    monday.setDate(d.getDate() + diffToMonday);
    monday.setHours(0, 0, 0, 0);
    const sunday = new Date(monday);
    sunday.setDate(monday.getDate() + 6);
    sunday.setHours(23, 59, 59, 999);
    return { monday, sunday };
}

const now = nowBKK();
const { monday, sunday } = getWeekRange(now);
const lastMonday = new Date(monday); lastMonday.setDate(monday.getDate() - 7);
const lastSunday = new Date(sunday); lastSunday.setDate(sunday.getDate() - 7);

// ── Parse date dd/MM/YYYY (รองรับปีพุทธ) ───────────────────
function parseDate(str) {
    if (!str || str === 'NULL' || str === 'EMPTY') return null;
    const parts = str.toString().trim().split('/');
    if (parts.length !== 3) return null;
    let [d, m, y] = parts.map(Number);
    if (y > 2400) y -= 543;
    if (y < 100) y += 2000;
    return new Date(y, m - 1, d);
}

// ── Normalize company name ───────────────────────────────────
function normalize(s) { return s.replace(/\s+/g, ' ').toLowerCase().trim(); }

// ── Collect data ─────────────────────────────────────────────
let totalThis = 0, totalLast = 0;
const THIS = { Green: [], Yellow: [], Red: [] };
const LAST = { Green: [], Yellow: [], Red: [] };
const allPrevCompanies = new Set();

items.forEach(item => {
    const d = item.json;
    if (!d.date) return;
    const dt = parseDate(d.date);
    if (!dt) return;

    const status  = (d.Status  || '').trim();
    const company = (d.Company || '-').trim();
    const entry   = { company };

    if (dt >= monday && dt <= sunday) {
        totalThis++;
        if (THIS[status]) THIS[status].push(entry);
    } else if (dt >= lastMonday && dt <= lastSunday) {
        totalLast++;
        if (LAST[status]) LAST[status].push(entry);
    }

    // ทุก row ที่ date < monday = เคยมีในระบบแล้ว
    if (dt < monday) {
        allPrevCompanies.add(normalize(company));
    }
});

// ── NEW = บริษัทที่ไม่เคยมีใน sheet เลย ─────────────────────
function getNew(thisArr) {
    return thisArr.filter(e => !allPrevCompanies.has(normalize(e.company)));
}

// ── Math helpers ─────────────────────────────────────────────
function pct(a, b) {
    if (b === 0) return a > 0 ? '+100%' : '0%';
    const p = Math.round(((a - b) / b) * 100);
    return (p >= 0 ? '+' : '') + p + '%';
}
function arrowStr(a, b) { return a > b ? '▲' : a < b ? '▼' : '–'; }
function arrowCol(a, b)  { return a > b ? '#43A047' : a < b ? '#E53935' : '#888888'; }
function diffStr(a, b)   { const d = a - b; return d === 0 ? '–' : (d > 0 ? `+${d}` : `${d}`); }

// ── Date label ───────────────────────────────────────────────
const fmtDay  = d => d.toLocaleDateString('en-GB', { day: 'numeric' });
const fmtFull = d => d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
const fmtShrt = d => d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
function weekLabel(m, s) {
    return m.getMonth() === s.getMonth()
        ? `${fmtDay(m)} - ${fmtFull(s)}`
        : `${fmtShrt(m)} - ${fmtFull(s)}`;
}
const thisLabel = weekLabel(monday, sunday);
const lastLabel = weekLabel(lastMonday, lastSunday);
const today     = now.toLocaleDateString('en-GB', { day: '2-digit', month: '2-digit', year: 'numeric' });



// ── Entry list ───────────────────────────────────────────────
function makeList(arr) {
    if (arr.length === 0) return [{
        type: "text", text: "-", size: "sm", color: "#AAAAAA", margin: "sm"
    }];
    return arr.map(({ company }) => ({
        type: "text",
        text: `• ${company}`,
        size: "sm", color: "#333333", wrap: true, margin: "sm"
    }));
}

function makeNewList(arr) {
    if (arr.length === 0) return [];
    return arr.map(({ company }) => ({
        type: "text",
        text: `✦ NEW: ${company}`,
        size: "sm", color: "#1565C0", wrap: true, weight: "bold", margin: "sm"
    }));
}

// ── Compare stat box ─────────────────────────────────────────
function makeStatBox(count, last, label, bg, numCol, subCol) {
    const ac = arrowCol(count, last);
    return {
        type: "box", layout: "vertical", flex: 1,
        backgroundColor: bg, cornerRadius: "10px", paddingAll: "10px",
        contents: [
            { type: "text", text: `${count}`, weight: "bold", size: "xl", color: numCol, align: "center" },
            { type: "text", text: label, size: "xxs", color: subCol, align: "center" },
            { type: "separator", margin: "sm" },
            {
                type: "box", layout: "horizontal", margin: "sm", justifyContent: "center",
                contents: [
                    { type: "text", text: `${arrowStr(count, last)} ${diffStr(count, last)}`, size: "xs", color: ac, flex: 0 },
                    { type: "text", text: `  ${pct(count, last)}`, size: "xxs", color: "#888888", flex: 0 }
                ]
            },
            { type: "text", text: `prev: ${last}`, size: "xxs", color: "#AAAAAA", align: "center" }
        ]
    };
}

// ── Status section ───────────────────────────────────────────
function makeSection(title, arr, bg, titleCol, countCol) {
    const newItems = makeNewList(getNew(arr));
    return {
        type: "box", layout: "vertical",
        backgroundColor: bg, cornerRadius: "8px", paddingAll: "12px",
        contents: [
            {
                type: "box", layout: "horizontal",
                contents: [
                    { type: "text", text: title, weight: "bold", color: titleCol, size: "sm", flex: 1 },
                    { type: "text", text: `${arr.length} ราย`, color: countCol, size: "sm", align: "end", flex: 0 }
                ]
            },
            ...makeList(arr),
            ...(newItems.length > 0 ? [
                { type: "separator", margin: "sm" },
                { type: "text", text: "✦ บริษัทใหม่ในระบบ", size: "xxs", color: "#1565C0", margin: "sm", weight: "bold" },
                ...newItems
            ] : [])
        ]
    };
}

// ── Total diff ───────────────────────────────────────────────
const tAC   = arrowCol(totalThis, totalLast);
const tDiff = diffStr(totalThis, totalLast);
const tPct  = pct(totalThis, totalLast);
const tArr  = arrowStr(totalThis, totalLast);

// ── Flex Bubble ──────────────────────────────────────────────
const bubble = {
    type: "bubble",
    header: {
        type: "box", layout: "horizontal",
        backgroundColor: "#1565C0", paddingAll: "20px",
        contents: [
            {
                type: "box", layout: "vertical", flex: 1,
                contents: [
                    { type: "text", text: "MoM WEEKLY REPORT", weight: "bold", color: "#FFFFFF", size: "md" },
                    { type: "text", text: "สรุปรายงานรายสัปดาห์", color: "#90CAF9", size: "xxs", margin: "xs" },
                    { type: "text", text: thisLabel, color: "#FFD54F", size: "xs", margin: "xs", weight: "bold" }
                ]
            },
            {
                type: "box", layout: "vertical", flex: 0,
                justifyContent: "center", alignItems: "center",
                contents: [
                    { type: "text", text: "รวม", color: "#90CAF9", size: "xxs", align: "center" },
                    { type: "text", text: `${totalThis}`, color: "#FFFFFF", size: "xxl", weight: "bold", align: "center" },
                    { type: "text", text: "ราย", color: "#90CAF9", size: "xxs", align: "center" },
                    {
                        type: "box", layout: "horizontal", margin: "xs", justifyContent: "center",
                        contents: [{ type: "text", text: `${tArr} ${tDiff}`, size: "xs", color: tAC, flex: 0 }]
                    },
                    { type: "text", text: tPct, size: "xxs", color: "#FFD54F", align: "center" }
                ]
            }
        ]
    },
    body: {
        type: "box", layout: "vertical", paddingAll: "16px", spacing: "md",
        contents: [
            {
                type: "box", layout: "horizontal", spacing: "sm",
                contents: [
                    makeStatBox(THIS.Green.length,  LAST.Green.length,  "โอกาสสูง",   "#E8F5E9", "#1B5E20", "#388E3C"),
                    makeStatBox(THIS.Yellow.length, LAST.Yellow.length, "รอติดตาม",   "#FFFDE7", "#E65100", "#F57C00"),
                    makeStatBox(THIS.Red.length,    LAST.Red.length,    "พักไว้ก่อน", "#FFEBEE", "#B71C1C", "#C62828")
                ]
            },

            {
                type: "box", layout: "horizontal",
                backgroundColor: "#F0F4FA", cornerRadius: "6px", paddingAll: "8px",
                contents: [
                    { type: "text", text: "📅 เทียบกับ:", size: "xxs", color: "#7A90B0", flex: 0 },
                    { type: "text", text: ` ${lastLabel}  (${totalLast} ราย)`, size: "xxs", color: "#1565C0", flex: 1, weight: "bold" }
                ]
            },
            { type: "separator" },
            makeSection("Green - โอกาสสูง",  THIS.Green,  "#E8F5E9", "#1B5E20", "#388E3C"),
            makeSection("Yellow - รอติดตาม", THIS.Yellow, "#FFFDE7", "#E65100", "#F57C00"),
            makeSection("Red - พักไว้ก่อน",  THIS.Red,   "#FFEBEE", "#B71C1C", "#C62828")
        ]
    },
    footer: {
        type: "box", layout: "horizontal",
        backgroundColor: "#F0F4FA", paddingAll: "10px",
        contents: [
            { type: "text", text: "รายงานประจำสัปดาห์", size: "xxs", color: "#7A90B0", flex: 1 },
            { type: "text", text: today, size: "xxs", color: "#7A90B0", align: "end" }
        ]
    }
};

return {
    line_payload: {
        to: "U39ad8f7118178f72fa5a8dde0b1c598a",
        messages: [{
            type: "flex",
            altText: `MoM Weekly Report ${thisLabel} รวม ${totalThis} ราย (${tArr}${tDiff} จาก week ที่แล้ว)`,
            contents: bubble
        }]
    }
};

